package com.productionhouse.crm.audio.dubbing.api;
import com.productionhouse.crm.audio.dubbing.dto.*;import com.productionhouse.crm.audio.dubbing.service.DubbingSessionService;import jakarta.validation.Valid;import org.springframework.data.domain.Page;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.time.LocalDateTime;
@RestController @RequestMapping("/api/audio/dubbing") public class DubbingSessionController{private final DubbingSessionService service;public DubbingSessionController(DubbingSessionService service){this.service=service;}
@GetMapping @PreAuthorize("hasAuthority('DUBBING_READ')") public Page<DubbingSessionResponse> list(@RequestParam(required=false)String q,@RequestParam(required=false)String status,@RequestParam(required=false)String projectRef,@RequestParam(required=false)Long singerId,@RequestParam(required=false)String language,@RequestParam(required=false)LocalDateTime from,@RequestParam(required=false)LocalDateTime to,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="createdAt")String sort,@RequestParam(defaultValue="desc")String direction){return service.list(q,status,projectRef,singerId,language,from,to,page,size,sort,direction);}
@GetMapping("/{id}") @PreAuthorize("hasAuthority('DUBBING_READ')") public DubbingSessionResponse get(@PathVariable Long id){return service.get(id);}
@PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAuthority('DUBBING_WRITE')") public DubbingSessionResponse create(@Valid @RequestBody DubbingSessionRequest request){return service.create(request);}
@PutMapping("/{id}") @PreAuthorize("hasAuthority('DUBBING_WRITE')") public DubbingSessionResponse update(@PathVariable Long id,@Valid @RequestBody DubbingSessionRequest request){return service.update(id,request);}
@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("hasAuthority('DUBBING_DELETE')") public void delete(@PathVariable Long id){service.delete(id);}}
